<?php
declare(strict_types=1);
require __DIR__.'/_auth.php';$user=$auth->requireLogin(true);$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$password=(string)($_POST['password']??'');if(strlen($password)<12)$errors[]='Password must be at least 12 characters.';if($password!==(string)($_POST['confirm_password']??''))$errors[]='Passwords do not match.';if(!$errors){$auth->users()->password($user['id'],$password,false);$auth->audit()->log('PASSWORD_CHANGED',$user['id'],$user['username']);$_SESSION['auth']['must_change_password']=false;$_SESSION['flash']='Password changed.';redirect('index.php');}}
$title='Change Password';$activePage='';require __DIR__.'/partials/header.php';?>
<?php foreach($errors as $error):?><div class="alert error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel form-section"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="panel-head"><div><h2>Choose a new password</h2><p>A minimum of 12 characters is required.</p></div></div><div class="form-grid"><label>New Password<input type="password" name="password" autocomplete="new-password" required minlength="12"></label><label>Confirm Password<input type="password" name="confirm_password" autocomplete="new-password" required minlength="12"></label></div><div class="form-actions form-pad"><button class="btn primary">Change password</button></div></form><?php require __DIR__.'/partials/footer.php';?>
